import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bir görseli döndürmek ya da çevirmek saniyeler sürer. Program kurmazsınız, fotoğrafınız cihazınızdan ayrılmaz ve sonunda doğru yönde bir görsel indirirsiniz.</p>\n<p>Bu yazı, işlemi altı adımda anlatıyor. İster tek bir selfie ister bütün bir tatil albümü düzeltin, adımlar aynıdır.</p>\n<p>Sonunda doğru açıyı nasıl seçeceğinizi, aynalı selfieleri nasıl düzelteceğinizi ve döndürmenin kalıcı olmamasının nedenini öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: neler gerekli</h2>\n<p>Tek ihtiyacınız, düzeltilecek fotoğraflar ve modern bir tarayıcıdır. Dosyalarınızın nerede olduğunu bilin.</p>\n<p>Orijinal fotoğrafların bir yedeğini alın. Döndürülen fotoğraf ayrı bir dosyadır; orijinal güvenlik ağınızdır.</p>\n<p>Sorunu belirleyin: fotoğraf yan mı duruyor, baş aşağı mı, aynalı mı, hafif eğik mi? Sorun, çözümü belirler.</p>\n<h2 id=\"step-by-step\">Görsel döndürme altı adımda</h2>\n<p>Önce aracı açın ve fotoğrafı yükleyin. Önizlemede fotoğrafın nasıl durduğunu görün.</p>\n<p>Sonra yönü seçin: 90 derece sağa, 90 derece sola ya da 180 derece. Önizleme anında güncellenir.</p>\n<p>Son olarak sonucu kontrol edip indirin. Önizlemeyi atlamayın; yanlış yönde indirmek zaman kaybıdır.</p>\n<ol>\n<li>Döndürme aracını açın ve fotoğrafınızı yükleyin.</li>\n<li>90 derece sağa, sola ya da 180 derece döndürmeyi seçin.</li>\n<li>Gerekirse aynalı selfie için yatay çevirmeyi uygulayın.</li>\n<li>Eğik fotoğraflar için özel açıyı kaydırıcıyla ayarlayın.</li>\n<li>Sonucu önizlemede kontrol edin.</li>\n<li>Düzeltilen görseli indirin.</li>\n</ol>\n<h2 id=\"choosing-the-right-angle\">Doğru açıyı seçmek</h2>\n<p>Yan duran fotoğraf için 90 derece kullanın. Bir kez döndürmek genellikle yeterlidir.</p>\n<p>Baş aşağı duran fotoğraf için 180 derece kullanın. İki kez 90 derece döndürmekle aynıdır.</p>\n<p>Hafif eğik fotoğraf için özel açı kullanın. 2-3 derecelik düzeltme genellikle yeterlidir.</p>\n<h2 id=\"using-custom-angles\">Eğik fotoğraflar için özel açılar</h2>\n<p>Özel açı kaydırıcısıyla fotoğrafı derece derece döndürün. Ufuk çizgisini izleyin; çizgi yatay olunca durun.</p>\n<p>Küçük açılar az kırpar. 2-3 derecelik düzeltmede kayıp önemsiz kalır.</p>\n<p>Büyük açılar çok kırpar. 10 derecenin üzerindeki düzeltme, fotoğrafın önemli kısmını kesebilir.</p>\n<h2 id=\"flipping-a-mirrored-selfie\">Aynalı selfieyi çevirmek</h2>\n<p>Ön kameralar aynalı çeker. Selfie size doğru görünür ama başkalarına ters görünür.</p>\n<p>Yatay çevirme aynayı düzeltir. Yazılar doğru okunur, yüz simetrisi gerçeğe döner.</p>\n<p>Telefon ayarlarından aynalı çekimi kapatın. Böylece selfieler baştan doğru çıkar.</p>\n<h2 id=\"rotating-a-batch\">Bir grup fotoğrafı döndürmek</h2>\n<p>Tatilde çekilen onlarca fotoğraf aynı yönde yan olabilir. Hepsini aynı anda yükleyip toplu döndürün.</p>\n<p>Toplu döndürmede her fotoğraf için aynı açıyı kullanın. Hepsi aynı yönde çekildiyse tek işlem yeterlidir.</p>\n<p>Farklı yönlerdeki fotoğrafları ayırın. Karışık yönler toplu işlemde hata çıkarır.</p>\n<h2 id=\"choosing-output-format\">Çıktı formatını seçmek</h2>\n<p>Fotoğraflar için JPG kullanın. Küçük dosyalar, her yerde açılır.</p>\n<p>Saydam görseller için PNG kullanın. JPG saydamlığı desteklemez.</p>\n<p>Formatı değiştirmeniz gerekmiyorsa orijinal formatı koruyun. Gereksiz dönüştürme kalite kaybettirir.</p>\n<h2 id=\"checking-your-result\">İndirmeden önce sonucu kontrol etmek</h2>\n<p>Her zaman önizlemeyi kontrol edin. Fotoğrafın doğru yönde durduğundan emin olun.</p>\n<p>Yazıları okuyun. Yazı doğru okunuyorsa yön doğrudur; ters okunuyorsa çevirme gerekir.</p>\n<p>Şüphede kalırsanız indirmeden önce bir kez daha döndürün. Doğru yön, ilk bakışta belli olur.</p>\n<h2 id=\"fixing-scanned-documents\">Taranan belgeleri düzeltmek</h2>\n<p>Taramalar genellikle yan çıkar. Belgeyi okumak için 90 derece döndürmek gerekir.</p>\n<p>Taranan belgeleri döndürünce kontrol edin. Yazılar doğru yönde okunmalıdır.</p>\n<p>Belgeleri döndürüp PDF'ye çevirin. PDF belgelerin paylaşım formatıdır.</p>\n<h2 id=\"rotating-on-mobile\">Telefon ve tablette görsel döndürmek</h2>\n<p>Modern mobil tarayıcılar aracı tam olarak destekler. Telefonda fotoğraf seçip döndürebilir ve sonucu indirebilirsiniz.</p>\n<p>Telefonda indirilenler genelde İndirilenler klasöründe durur. Bulmak zorlaşırsa tarayıcının indirme listesine bakın.</p>\n<p>Telefon galerisinin kendi döndürme özelliği de vardır. Hızlı düzeltmeler için galeri yeterlidir.</p>\n<h2 id=\"troubleshooting\">Sorun giderme: döndürme kalıcı olmadığında</h2>\n<p>Fotoğraf döndürüldükten sonra yine yan görünüyorsa EXIF yönü kalmış olabilir. Pikselleri gerçekten döndüren aracı kullanın.</p>\n<p>Bazı programlar EXIF'i yok sayar. Döndürülen fotoğrafı farklı bir programda açıp kontrol edin.</p>\n<p>Sorun devam ederse dosyayı PNG olarak kaydedin. PNG, EXIF yönü taşımaz; yön piksellerde kalır.</p>\n<h2 id=\"quick-tips\">Daha hızlı döndürmek için hızlı ipuçları</h2>\n<p>Toplu döndürme kullanın. Aynı yöndeki fotoğrafları tek seferde düzeltin.</p>\n<p>Klavye kısayollarını öğrenin. Ok tuşları, döndürmeyi hızlandırır.</p>\n<p>Önizlemeyi atlamayın. Birkaç saniyelik kontrol, yanlış indirmeyi önler.</p>\n<h2 id=\"rotating-animated-gifs\">Animasyonlu GIF'leri döndürmek</h2>\n<p>Animasyonlu GIF'leri döndürmek, her kareyi döndürmek demektir. Araç, tüm kareleri aynı açıyla döndürür.</p>\n<p>GIF döndürmede kalite korunur. Kareler kayıpsız işlenir; animasyon bozulmaz.</p>\n<p>Büyük GIF'ler yavaş işlenebilir. Sabırlı olun; işlem bitince indirin.</p>\n<h2 id=\"rotation-for-id-photos\">Kimlik ve pasaport fotoğraflarını döndürmek</h2>\n<p>Kimlik fotoğrafları dik durmalıdır. Yan duran fotoğraf başvuruda reddedilir.</p>\n<p>Fotoğrafı döndürdükten sonra boyutları kontrol edin. Kimlik fotoğraflarında boyut kuralları katıdır.</p>\n<p>Arka planı kontrol edin. Kimlik fotoğraflarında arka plan düz ve açık renk olmalıdır.</p>\n<h2 id=\"rotation-shortcuts\">Klavye kısayolları ve pano</h2>\n<p>Ok tuşlarıyla döndürme yönünü hızlı seçebilirsiniz. Kısayollar, toplu işlerde zaman kazandırır.</p>\n<p>Panodan yapıştırma da çalışır. Ekran görüntüsünü kopyalayıp araca yapıştırabilirsiniz.</p>\n<p>Kısayolları araç sayfasında öğrenin. Her araç, kendi kısayollarını listeler.</p>\n<h2 id=\"rotation-vs-other-tools\">Döndürme ve diğer düzenleme araçları</h2>\n<p>Döndürme, en basit düzenlemedir. Kırpma, boyutlandırma ve parlaklık daha karmaşıktır.</p>\n<p>Önce döndürün, sonra diğer düzenlemeleri yapın. Sıralama, gereksiz kırpmayı önler.</p>\n<p>Tüm düzenlemeler bitince indirin. Ara adımlarda indirmek kalite kaybettirir.</p>\n<p>Adım adım ilerleyin ve her fotoğrafı indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/gorsel-dondur-cevir-rehberi\">Görsel döndürme ve çevirme kılavuzuna</a> bakın; EXIF sorunları için <a href=\"/tr/blog/gorsel-yonlendirme-exif-dondurme\">EXIF yönlendirme sorunları</a> yazısı yardımcı olur. Kırpma için <a href=\"/tr/gorsel-kirp\">görsel kırpıcı</a>, boyut için <a href=\"/tr/gorsel-boyutlandir\">görsel boyutlandırıcı</a> hazırdır; araç ise <a href=\"/tr/gorsel-dondur-cevir\">görsel döndürme ve çevirme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Telefonda bir fotoğrafı 90 derece nasıl döndürürüm?","answer":"Döndürme aracını telefon tarayıcısında açın, fotoğrafı seçin ve 90 derece döndürmeyi seçin. Önizlemede yönü kontrol edip indirin. Telefon galerisinin kendi döndürme özelliği de hızlı düzeltmeler için yeterlidir."},{"question":"Fotoğrafımı kalite kaybetmeden döndürebilir miyim?","answer":"Evet, 90 derecelik döndürme kayıpsızdır; JPG bile bu açıda kalite kaybetmez. Özel açılar hafif bulanıklık yapabilir; PNG döndürme her zaman kayıpsızdır. Kalite kaybı yaşamamak için özel açıları küçük tutun."},{"question":"Baş aşağı duran bir fotoğrafı nasıl düzeltirim?","answer":"180 derece döndürün; iki kez 90 derece döndürmekle aynıdır. Önizlemede yazıların doğru okunduğunu kontrol edin. Fotoğraf hâlâ ters görünüyorsa dikey çevirmeyi deneyin."},{"question":"Birden fazla fotoğrafı aynı anda döndürebilir miyim?","answer":"Evet. Aynı yönde yan duran tüm fotoğrafları aynı anda yükleyip toplu döndürün. Farklı yönlerdeki fotoğrafları ayırın; karışık yönler toplu işlemde hata çıkarır."},{"question":"Fotoğrafım döndürdükten sonra neden hâlâ yan duruyor?","answer":"Çünkü EXIF yönlendirme verisi kalmış olabilir. Bazı programlar EXIF'i okur ve fotoğrafı yeniden yan çevirir. Pikselleri gerçekten döndüren aracı kullanın; sorun devam ederse dosyayı PNG olarak kaydedin."},{"question":"Yalnızca biraz eğik olan bir fotoğrafı nasıl düzeltirim?","answer":"Özel açı kaydırıcısıyla 2-3 derece döndürün. Önizlemede ufuk çizgisini izleyin; çizgi yatay olunca durun. Küçük açılar az kırpar; büyük açılar fotoğrafın köşelerini keser."}];
